const BASE_URL = import.meta.env.VITE_API_URL ?? "https://smartloansbackend.azurewebsites.net";

export interface DemandSignal {
  demandSignalId: number;
  companyId: number;
  channelId: number;
  customerPhone: string; // Masked from backend
  clientId: number | null;
  marketingLeadAttributionId: number | null;
  concept: string;
  origin: string;
  residenceZoneText: string | null;
  workZoneText: string | null;
  preferredZoneText: string;
  preferredZoneName: string | null;
  preferredZoneLat: number | null;
  preferredZoneLng: number | null;
  frequency: string | null;
  preferredTime: string | null;
  currentSolution: string | null;
  painPoint: string | null;
  wouldUse: string | null;
  notifyOptIn: boolean;
  optInAt: string | null;
  intentLevel: string;
  isExistingClient?: boolean; // From backend response
  sourceId?: string; // From backend response
  headline?: string; // From backend response
  phoneLast4?: string; // From backend response
  created_At: string;
  updated_at: string | null;
}

export interface DemandSignalFilter {
  companyId: number;
  startDate?: string; // YYYY-MM-DD
  endDate?: string;   // YYYY-MM-DD
  concept?: string;
  origin?: string;
  intentLevel?: string;
  sourceId?: string;
}

export interface DemandSignalListResponse {
  result: DemandSignal[];
}

export interface ZoneSummary {
  zoneName: string;
  lat: number | null;
  lng: number | null;
  concept: string;
  people: number;
  alta: number;
  media: number;
  baja: number;
  pctRecurring: number;
  topPreferredTime: string | null;
  newProspects: number;
  existingClients: number;
  optIns: number;
}

export interface ZoneSummaryFilter {
  companyId: number;
  startDate?: string; // YYYY-MM-DD
  endDate?: string;   // YYYY-MM-DD
  concept?: string;
  origin?: string;
}

export interface ZoneSummaryResponse {
  result: ZoneSummary[];
}

// GET ALL Demand Signals
export async function getAllDemandSignals(filter: DemandSignalFilter): Promise<DemandSignal[]> {
  const res = await fetch(BASE_URL + "/all_demandSignals", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(filter),
  });
  if (!res.ok) throw new Error(await res.text());
  const data: DemandSignalListResponse = await res.json();
  return data.result ?? [];
}

// GET Zone Summary
export async function getZoneSummary(filter: ZoneSummaryFilter): Promise<ZoneSummary[]> {
  const res = await fetch(BASE_URL + "/demandSignals/zoneSummary", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(filter),
  });
  if (!res.ok) throw new Error(await res.text());
  const data: ZoneSummaryResponse = await res.json();
  return data.result ?? [];
}
