import { useIonViewWillEnter } from '@ionic/react';
import { useUser } from '../../../contexts/UserContext';
import { useToast } from '../../../hooks/useToast';
import { onDataChanged } from '../../../utils/refreshBus';
import { getAllDemandSignals, getZoneSummary, DemandSignal, DemandSignalFilter, ZoneSummary } from '../../../api/demandSignalApi';

const CONCEPTS = [
  { value: 'autoservicio_24h', label: 'Autoservicio 24h' },
  { value: 'lockers', label: 'Lockers' },
  { value: 'qr_gmo', label: 'QR GMO' },
];
const ORIGINS = [
  { value: 'whatsapp_ad', label: 'Anuncio de WhatsApp' },
  { value: 'organic_chat', label: 'Chat Orgánico' },
];
const INTENT_LEVELS = [
  { value: 'alta', label: 'Alta' },
  { value: 'media', label: 'Media' },
  { value: 'baja', label: 'Baja' },
];

export const useDemandSignal = () => {
  const { companyId } = useUser();
  const { showToast, toastProps } = useToast();
  const [items, setItems] = useState<DemandSignal[]>([]);
  const [zoneSummaries, setZoneSummaries] = useState<ZoneSummary[]>([]);
  const [loading, setLoading] = useState(false);
  const [currentTab, setCurrentTab] = useState('signals'); // 'signals' or 'zones'

  const [filters, setFilters] = useState<DemandSignalFilter>({
    companyId: companyId,
    startDate: '',
    endDate: '',
    concept: '',
    origin: '',
    intentLevel: '',
    sourceId: ''
  });

  const loadData = useCallback(async () => {
    if (!companyId) return;
    setLoading(true);
    try {
      const signals = await getAllDemandSignals(filters);
      setItems(signals);

      const zoneFilters = {
        companyId: filters.companyId,
        startDate: filters.startDate,
        endDate: filters.endDate,
        concept: filters.concept,
        origin: filters.origin,
      };
      const summaries = await getZoneSummary(zoneFilters);
      setZoneSummaries(summaries);
    } catch (err) {
      showToast((err as Error).message ?? 'Error desconocido al cargar señales de demanda', 'danger');
    } finally {
      setLoading(false);
    }
  }, [companyId, filters, showToast]);

  useEffect(() => {
    setFilters(prev => ({ ...prev, companyId: companyId }));
    loadData();
  }, [companyId, loadData]);

  useIonViewWillEnter(() => {
    loadData();
  });

  useEffect(() => onDataChanged(() => loadData()), [loadData]);

  const handleFilterChange = useCallback((key: keyof DemandSignalFilter, value: string) => {
    setFilters(prev => ({ ...prev, [key]: value }));
  }, []);

  const applyFilters = useCallback(() => {
    loadData();
  }, [loadData]);

  return {
    items,
    zoneSummaries,
    loading,
    toastProps,
    currentTab,
    setCurrentTab,
    filters,
    handleFilterChange,
    applyFilters,
    CONCEPTS,
    ORIGINS,
    INTENT_LEVELS,
  };
};

export type DemandSignalVM = ReturnType<typeof useDemandSignal>;
